package dev.pocketengine.features.local.project;

import static org.junit.Assert.*;
import dev.pocketengine.features.EngineModule;
import org.json.*;
import org.junit.Test;

/** Native command proposal contracts, not process/device/provider evidence. */
public final class ProjectCommandPlanTest {
    private static final class Local implements EngineModule {
        final JSONObject source=new JSONObject();boolean pty=true;
        Local()throws Exception{source.put("checkout",new JSONObject().put("id","checkout").put("projectId","project")).put("files",new JSONArray().put(new JSONObject().put("path","main.mjs").put("content","console.log('actual source');\n")));}
        public String id(){return "local";}public JSONObject snapshot(){return new JSONObject();}
        public JSONObject handle(String command,JSONObject input)throws Exception{return switch(command){case "export"->ProjectSources.copy(source);case "probe"->new JSONObject();case "listJobs"->new JSONObject().put("termuxJobs",new JSONArray());case "project.runtime.describe"->new JSONObject().put("identity","a".repeat(64)).put("canExecute",true).put("ptyAvailable",pty).put("tools",new JSONArray().put(new JSONObject().put("name","node").put("hashVerified",true)));default->throw new IllegalArgumentException(command);};}
        JSONObject request()throws Exception{return new JSONObject().put("checkoutId","checkout").put("runtimeId","managed_process_v1").put("intent","command").put("expectedSourceDigest",ProjectSources.describe(source).getString("sourceDigest")).put("executable","node").put("argv",new JSONArray().put("main.mjs")).put("cwd",".").put("env",new JSONObject().put("APP_LABEL","ordinary-canary"));}
    }
    private static JSONObject reseal(JSONObject plan)throws Exception{plan=ProjectSources.copy(plan);plan.remove("planId");plan.remove("planDigest");JSONArray steps=plan.getJSONArray("steps");for(int i=0;i<steps.length();i++)steps.getJSONObject(i).remove("hostAction");String digest=ProjectSources.digest(plan);return plan.put("planId",digest).put("planDigest",digest);}
    @Test public void exactCommandUsesOriginalSourceSingleStepAndConservativeEffects()throws Exception {
        Local local=new Local();JSONObject plan=ProjectBuildPlan.verified(ProjectBuildPlan.create(local,local.request()));assertEquals("command",plan.getString("intent"));assertEquals("native_command",plan.getString("ecosystem"));assertEquals(1,plan.getJSONArray("steps").length());assertTrue(plan.getBoolean("available"));JSONObject action=ProjectBuildPlan.step(plan,"command");assertEquals("project.runtime.run",action.getString("localCommand"));assertEquals("literal_argv",action.getJSONObject("effects").getString("argumentTransport"));assertTrue(action.getJSONObject("effects").getBoolean("writes"));assertTrue(action.getJSONObject("effects").getBoolean("networkMayBeUsed"));assertFalse(action.getJSONObject("effects").getBoolean("scopeEnforced"));assertEquals("ordinary-canary",action.getJSONObject("payload").getJSONObject("environment").getString("APP_LABEL"));
    }
    @Test public void explicitPtyPlanIncludesBoundedSameExecutionInputButUnavailableNativeDoesNotLaunch()throws Exception {
        Local local=new Local();JSONObject request=local.request().put("runMode","owned_service").put("terminal","pty").put("inputByteLimit",1200).put("rows",30).put("columns",90);JSONObject plan=ProjectBuildPlan.verified(ProjectBuildPlan.create(local,request)),payload=ProjectBuildPlan.step(plan,"command").getJSONObject("payload");assertTrue(plan.getBoolean("available"));assertTrue(payload.getBoolean("interactiveInputExplicitlyIncluded"));assertEquals(1200,payload.getInt("inputByteLimit"));assertTrue(ProjectCommandSpec.inputScopeDigest(payload).matches("[a-f0-9]{64}"));local.pty=false;assertFalse(ProjectBuildPlan.create(local,request).getBoolean("available"));
    }
    @Test public void commandDoesNotSilentlyIgnoreEditWatchOrAlternativeIntentFields()throws Exception {
        Local local=new Local();for(String field:new String[]{"ecosystem","target","path","content","expectedHash","edits","devWatch","liveEditPaths","liveEditServiceExecutionId","artifactSelection"})assertThrows(field,IllegalArgumentException.class,()->ProjectBuildPlan.create(local,local.request().put(field,"not an implicit second effect")));assertThrows(IllegalArgumentException.class,()->ProjectBuildPlan.create(local,local.request().put("runtimeId","termux")));
    }
    @Test public void resealedModelJsonCannotTurnCommandIntoReadonlySandboxOrUnboundPayload()throws Exception {
        Local local=new Local();JSONObject original=ProjectBuildPlan.create(local,local.request());for(String field:new String[]{"writes","networkMayBeUsed","scopeEnforced"}){JSONObject changed=ProjectSources.copy(original);changed.getJSONArray("steps").getJSONObject(0).getJSONObject("effects").put(field,field.equals("scopeEnforced"));JSONObject forged=reseal(changed);assertThrows(field,SecurityException.class,()->ProjectBuildPlan.verified(forged));}
        for(String field:new String[]{"devWatch","interactiveInputExplicitlyIncluded","shell"}){JSONObject changed=ProjectSources.copy(original);changed.getJSONArray("steps").getJSONObject(0).getJSONObject("payload").put(field,true);JSONObject forged=reseal(changed);assertThrows(field,SecurityException.class,()->ProjectBuildPlan.verified(forged));}
        JSONObject changed=ProjectSources.copy(original);changed.getJSONArray("steps").getJSONObject(0).getJSONObject("payload").put("expectedSourceDigest","b".repeat(64));JSONObject forged=reseal(changed);assertThrows(SecurityException.class,()->ProjectBuildPlan.verified(forged));
    }
    @Test public void inputShapeIsExactAndNeverAppendsLineBreaksOrTreatsEofAsText()throws Exception {
        JSONObject text=ProjectCommandSpec.inputRequest(new JSONObject().put("executionId","owned").put("action","text").put("text","ordinary 😀"));assertEquals("ordinary 😀",text.getString("text"));assertFalse(text.has("executionId"));assertThrows(IllegalArgumentException.class,()->ProjectCommandSpec.inputRequest(new JSONObject().put("action","eof").put("text","x")));assertThrows(IllegalArgumentException.class,()->ProjectCommandSpec.inputRequest(new JSONObject().put("action","resize").put("rows",3)));assertThrows(IllegalArgumentException.class,()->ProjectCommandSpec.inputRequest(new JSONObject().put("action","text").put("text","😀".repeat(1025))));
    }
    @Test public void redactedNativeCommandArgvStillHasAnExactCheckedReceiptWithoutRepeatingValues()throws Exception {
        Local local=new Local();JSONObject plan=ProjectBuildPlan.create(local,local.request()),step=ProjectBuildPlan.step(plan,"command"),payload=step.getJSONObject("payload");JSONObject job=new JSONObject().put("id","operation").put("operationId","operation").put("checkoutId","checkout").put("sourceDigest",plan.getString("sourceDigest")).put("kind","command").put("provider","managed_process").put("requestedExecutable","node").put("argumentValuesIncluded",false).put("argvCount",payload.getJSONArray("argv").length()).put("argvDigest",ProjectSources.digest(new JSONObject().put("argv",payload.getJSONArray("argv")))).put("status","failed").put("exitCode",13).put("receiptReceived",true).put("sourceCheckStatus","pre_exec_manifest_verified");
        JSONObject binding=new JSONObject().put("authority","native_host_operation").put("taskId","task").put("runId","run").put("coordinatorEpoch",1).put("operationId","operation"),route=ProjectSources.copy(binding).put("command","project.runtime.run").put("runtimeId","managed_process_v1").put("runtimeIdentity",plan.getString("runtimeIdentity")).put("projectId","project").put("checkoutId","checkout").put("planDigest",plan.getString("planDigest")).put("stepId","command").put("intent","command").put("sourceDigest",plan.getString("sourceDigest")).put("requestDigest",ProjectSources.digest(payload));job.put("projectExecution",route);
        var method=ProjectDevelopment.class.getDeclaredMethod("normalize",JSONObject.class,JSONObject.class,JSONObject.class,JSONObject.class,JSONObject.class);method.setAccessible(true);JSONObject actual=(JSONObject)method.invoke(null,plan,step,job,binding,null);assertEquals(13,actual.getInt("exitCode"));assertFalse(actual.has("requestedArgv"));
        for(String field:new String[]{"argvDigest","argvCount","argumentValuesIncluded"}){JSONObject changed=ProjectSources.copy(job);changed.put(field,field.equals("argvDigest")?"b".repeat(64):field.equals("argvCount")?99:true);var rejected=assertThrows(java.lang.reflect.InvocationTargetException.class,()->method.invoke(null,plan,step,changed,binding,null));assertTrue(rejected.getCause() instanceof SecurityException);}
        for(String key:new String[]{"requestDigest","runId","runtimeIdentity"}){JSONObject changed=ProjectSources.copy(job);changed.getJSONObject("projectExecution").put(key,"unrelated");var rejected=assertThrows(java.lang.reflect.InvocationTargetException.class,()->method.invoke(null,plan,step,changed,binding,null));assertTrue(rejected.getCause() instanceof SecurityException);}
        JSONObject legacy=ProjectSources.copy(plan).put("intent","run");var rejected=assertThrows(java.lang.reflect.InvocationTargetException.class,()->method.invoke(null,legacy,step,job,binding,null));assertTrue("old command receipt contract must not silently relax",rejected.getCause() instanceof SecurityException);
    }
}
